<div class="container-fluid py-4"><a class="btn btn-outline-secondary mb-3" href="<?= base_url('cliente/servicio_tecnico') ?>">← Volver</a><div class="card"><div class="card-body"><h2>Solicitar servicio técnico</h2><p class="text-muted">Describe el equipo y el problema; el equipo técnico revisará tu solicitud.</p><?php if ($this->session->flashdata('error')): ?><div class="alert alert-danger"><?= html_escape($this->session->flashdata('error')) ?></div><?php endif ?><?= form_open('cliente/servicio_tecnico/guardar') ?><div class="mb-3"><label class="form-label">Tipo de servicio</label><select class="form-select" name="tipo_servicio" id="tipo_servicio" required><option value="">Selecciona una opción</option><option value="1">Garantía</option><option value="2">Reparación o mantenimiento</option></select></div><div class="mb-3" id="contenedorGarantia" hidden><label class="form-label">Garantía vigente</label><select class="form-select" name="id_garantia" id="id_garantia"><option value="">Selecciona la garantía</option><?php foreach ($garantias as $garantia): ?><option value="<?= (int) $garantia->id_garantia ?>">#<?= (int) $garantia->id_garantia ?> · <?= html_escape($garantia->nombre_producto) ?> (vence <?= date('d/m/Y', strtotime($garantia->fecha_vencimiento)) ?>)</option><?php endforeach ?></select></div><div class="mb-3"><label class="form-label">Equipo</label><input class="form-control" name="nombre_equipo" maxlength="100" required></div><div class="mb-3"><label class="form-label">Descripción del problema</label><textarea class="form-control" name="descripcion_problema" rows="5" required></textarea></div><button class="btn btn-primary">Enviar solicitud</button><?= form_close() ?></div></div></div><script>document.addEventListener('DOMContentLoaded',function(){var tipo=document.getElementById('tipo_servicio'),contenedor=document.getElementById('contenedorGarantia'),garantia=document.getElementById('id_garantia');function actualizar(){var aplica=tipo.value==='1';contenedor.hidden=!aplica;garantia.required=aplica;if(!aplica){garantia.value='';}}tipo.addEventListener('change',actualizar);actualizar();});</script>
